import os
actors_dir = "heretek-swarm/heretek_swarm/actors"
if not os.path.isdir(actors_dir):
    print("NOT FOUND:", actors_dir)
else:
    for name in sorted(os.listdir(actors_dir)):
        path = os.path.join(actors_dir, name)
        if name.endswith(".py") and os.path.isfile(path):
            with open(path) as f:
                lines = len(f.readlines())
            print(f"{name}: {lines} lines")
        elif os.path.isdir(path):
            py_files = [f for f in os.listdir(path) if f.endswith(".py")]
            total = 0
            for pf in py_files:
                with open(os.path.join(path, pf)) as f:
                    total += len(f.readlines())
            print(f"[{name}/]: {total} lines across {len(py_files)} files")
